@page "/apply"
@using sv_b13664c42f6548f188be3e13ec5140b7.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="NavigateToStep" />

    @if (currentStep == 1)
    {
        <PersonalInfoStep Form="formState.Personal"
                          OnNext="HandlePersonalInfoNext"
                          EmailError="@emailError"
                          IsValidating="isValidatingEmail" />
    }
    else if (currentStep == 2)
    {
        <WorkHistoryStep Entries="formState.WorkEntries"
                         OnBack="GoBack"
                         OnNext="GoNext" />
    }
    else if (currentStep == 3)
    {
        <ReferencesStep References="formState.References"
                        OnBack="GoBack"
                        OnNext="GoNext" />
    }
    else if (currentStep == 4)
    {
        <CoverLetterStep @bind-CoverLetter="formState.CoverLetter"
                         OnBack="GoBack"
                         OnNext="GoNext" />
    }
    else if (currentStep == 5)
    {
        <ReviewStep FormState="formState"
                    OnBack="GoBack"
                    OnEditStep="NavigateToStep"
                    OnSubmit="HandleSubmit"
                    IsSubmitting="isSubmitting"
                    SubmittedId="submittedId" />
    }
</div>

@code {
    private ApplicationFormState formState = new();
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();
    private string? emailError;
    private bool isValidatingEmail;
    private bool isSubmitting;
    private int? submittedId;

    private void NavigateToStep(int step)
    {
        if (completedSteps.Contains(step))
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 1)
            currentStep--;
    }

    private void GoNext()
    {
        completedSteps.Add(currentStep);
        if (currentStep < 5)
            currentStep++;
    }

    private async Task HandlePersonalInfoNext()
    {
        emailError = null;
        isValidatingEmail = true;
        StateHasChanged();

        var isValid = await ApplicationService.ValidateEmailAsync(formState.Personal.Email);
        isValidatingEmail = false;

        if (!isValid)
        {
            emailError = "Email validation failed. Please use a valid email address.";
            return;
        }

        GoNext();
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        StateHasChanged();

        var application = formState.ToRecord();
        submittedId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitting = false;
    }
}

@namespace sv_b13664c42f6548f188be3e13ec5140b7.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 1; i <= StepNames.Length; i++)
    {
        var step = i;
        var isCurrent = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);
        var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";

        <div class="@cssClass" @onclick="() => HandleClick(step)" role="button" tabindex="0">
            <span class="step-number">
                @if (isCompleted && !isCurrent)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @step
                }
            </span>
            <span class="step-label">@StepNames[step - 1]</span>
        </div>

        @if (step < StepNames.Length)
        {
            <div class="step-connector @(isCompleted ? "completed" : "")"></div>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@namespace sv_b13664c42f6548f188be3e13ec5140b7.Components.Pages.Apply
@using sv_b13664c42f6548f188be3e13ec5140b7.Models

<div class="step-content">
    <h2>Personal Information</h2>

    <EditForm Model="Form" OnValidSubmit="HandleNext">
        <DataAnnotationsValidator />

        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <InputText id="fullName" @bind-Value="Form.FullName" class="form-control" />
            <ValidationMessage For="() => Form.FullName" />
        </div>

        <div class="form-group">
            <label for="email">Email *</label>
            <InputText id="email" @bind-Value="Form.Email" class="form-control" />
            <ValidationMessage For="() => Form.Email" />
            @if (!string.IsNullOrEmpty(EmailError))
            {
                <div class="validation-message">@EmailError</div>
            }
        </div>

        <div class="form-group">
            <label for="phone">Phone *</label>
            <InputText id="phone" @bind-Value="Form.Phone" class="form-control" />
            <ValidationMessage For="() => Form.Phone" />
        </div>

        <div class="form-group">
            <label for="address">Address *</label>
            <InputText id="address" @bind-Value="Form.Address" class="form-control" />
            <ValidationMessage For="() => Form.Address" />
        </div>

        <div class="step-buttons">
            <button type="submit" class="btn btn-primary" disabled="@IsValidating">
                @if (IsValidating)
                {
                    <span>Validating...</span>
                }
                else
                {
                    <span>Next</span>
                }
            </button>
        </div>
    </EditForm>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoForm Form { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public bool IsValidating { get; set; }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

@namespace sv_b13664c42f6548f188be3e13ec5140b7.Components.Pages.Apply
@using sv_b13664c42f6548f188be3e13ec5140b7.Models

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];

        <fieldset class="work-entry-card">
            <legend>Position @(index + 1)</legend>

            <div class="form-group">
                <label>Company Name *</label>
                <input type="text" @bind="entry.Company" class="form-control" />
            </div>

            <div class="form-group">
                <label>Job Title *</label>
                <input type="text" @bind="entry.Title" class="form-control" />
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Start Date *</label>
                    <input type="date" @bind="entry.StartDate" class="form-control" />
                </div>

                <div class="form-group">
                    <label>
                        <input type="checkbox" @bind="entry.IsCurrent" />
                        Currently working here
                    </label>
                </div>

                @if (!entry.IsCurrent)
                {
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" @bind="entry.EndDate" class="form-control" />
                    </div>
                }
            </div>

            <div class="form-group">
                <label>Description</label>
                <textarea @bind="entry.Description" class="form-control" rows="3"></textarea>
            </div>

            @if (Entries.Count > 1)
            {
                <button type="button" class="btn btn-danger btn-sm" @onclick="() => RemoveEntry(index)">
                    Remove
                </button>
            }
        </fieldset>
    }

    <button type="button" class="btn btn-secondary" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@(!IsValid)">Next</button>
    </div>

    @if (validationError is not null)
    {
        <div class="validation-message">@validationError</div>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryForm> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }

    private string? validationError;

    private bool IsValid => Entries.All(e =>
        !string.IsNullOrWhiteSpace(e.Company) &&
        !string.IsNullOrWhiteSpace(e.Title) &&
        e.StartDate.HasValue);

    private void AddEntry()
    {
        Entries.Add(new WorkEntryForm());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        if (!IsValid)
        {
            validationError = "Please fill in all required fields for each position.";
            return;
        }
        validationError = null;
        await OnNext.InvokeAsync();
    }
}

@namespace sv_b13664c42f6548f188be3e13ec5140b7.Components.Pages.Apply
@using sv_b13664c42f6548f188be3e13ec5140b7.Models

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];

        <fieldset class="reference-card">
            <legend>Reference @(index + 1)</legend>

            <div class="form-group">
                <label>Name *</label>
                <input type="text" @bind="reference.Name" class="form-control" />
            </div>

            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" @bind="reference.Relationship" class="form-control" />
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" @bind="reference.Email" class="form-control" />
                </div>

                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" @bind="reference.Phone" class="form-control" />
                </div>
            </div>

            @if (References.Count > 2)
            {
                <button type="button" class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">
                    Remove
                </button>
            }
        </fieldset>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-secondary" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@(!IsValid)">Next</button>
    </div>

    @if (validationError is not null)
    {
        <div class="validation-message">@validationError</div>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceForm> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }

    private string? validationError;

    private bool IsValid => References.Count >= 2 && References.Take(2).All(r =>
        !string.IsNullOrWhiteSpace(r.Name) &&
        !string.IsNullOrWhiteSpace(r.Relationship) &&
        !string.IsNullOrWhiteSpace(r.Email) &&
        !string.IsNullOrWhiteSpace(r.Phone));

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceForm());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        if (!IsValid)
        {
            validationError = "Please fill in all required fields for at least 2 references.";
            return;
        }
        validationError = null;
        await OnNext.InvokeAsync();
    }
}

@namespace sv_b13664c42f6548f188be3e13ec5140b7.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter below:</label>
        <textarea id="coverLetter"
                  class="form-control cover-letter-textarea"
                  rows="12"
                  maxlength="2000"
                  value="@CoverLetter"
                  @oninput="HandleInput"></textarea>
        <div class="character-count @(CoverLetter.Length > 1800 ? "warning" : "")">
            @CoverLetter.Length / 2000 characters
        </div>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="OnNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        if (value.Length <= 2000)
        {
            await CoverLetterChanged.InvokeAsync(value);
        }
    }
}

@namespace sv_b13664c42f6548f188be3e13ec5140b7.Components.Pages.Apply
@using sv_b13664c42f6548f188be3e13ec5140b7.Models

<div class="step-content">
    @if (SubmittedId.HasValue)
    {
        <div class="submission-confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received successfully.</p>
            <p class="application-id">Application ID: <strong>@SubmittedId</strong></p>
            <p>Please save this ID for your records.</p>
        </div>
    }
    else
    {
        <h2>Review &amp; Submit</h2>
        <p class="step-description">Please review your application before submitting.</p>

        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            <dl class="review-details">
                <dt>Full Name</dt><dd>@FormState.Personal.FullName</dd>
                <dt>Email</dt><dd>@FormState.Personal.Email</dd>
                <dt>Phone</dt><dd>@FormState.Personal.Phone</dd>
                <dt>Address</dt><dd>@FormState.Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var entry in FormState.WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span class="review-dates">
                        @entry.StartDate?.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            @foreach (var reference in FormState.References.Where(r => !string.IsNullOrWhiteSpace(r.Name)))
            {
                <div class="review-reference">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />
                    @reference.Email · @reference.Phone
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
            </div>
            <div class="review-cover-letter">
                @if (!string.IsNullOrWhiteSpace(FormState.CoverLetter))
                {
                    <p>@FormState.CoverLetter</p>
                }
                else
                {
                    <p class="text-muted"><em>No cover letter provided.</em></p>
                }
            </div>
        </section>

        <div class="step-buttons">
            <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-primary btn-submit" @onclick="OnSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormState FormState { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
