@page "/apply"
@using sv_b13664c42f6548f188be3e13ec5140b7.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="NavigateToStep" />

    @if (currentStep == 1)
    {
        <PersonalInfoStep Form="formState.Personal"
                          OnNext="HandlePersonalInfoNext"
                          EmailError="@emailError"
                          IsValidating="isValidatingEmail" />
    }
    else if (currentStep == 2)
    {
        <WorkHistoryStep Entries="formState.WorkEntries"
                         OnBack="GoBack"
                         OnNext="GoNext" />
    }
    else if (currentStep == 3)
    {
        <ReferencesStep References="formState.References"
                        OnBack="GoBack"
                        OnNext="GoNext" />
    }
    else if (currentStep == 4)
    {
        <CoverLetterStep @bind-CoverLetter="formState.CoverLetter"
                         OnBack="GoBack"
                         OnNext="GoNext" />
    }
    else if (currentStep == 5)
    {
        <ReviewStep FormState="formState"
                    OnBack="GoBack"
                    OnEditStep="NavigateToStep"
                    OnSubmit="HandleSubmit"
                    IsSubmitting="isSubmitting"
                    SubmittedId="submittedId" />
    }
</div>

@code {
    private ApplicationFormState formState = new();
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();
    private string? emailError;
    private bool isValidatingEmail;
    private bool isSubmitting;
    private int? submittedId;

    private void NavigateToStep(int step)
    {
        if (completedSteps.Contains(step))
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 1)
            currentStep--;
    }

    private void GoNext()
    {
        completedSteps.Add(currentStep);
        if (currentStep < 5)
            currentStep++;
    }

    private async Task HandlePersonalInfoNext()
    {
        emailError = null;
        isValidatingEmail = true;
        StateHasChanged();

        var isValid = await ApplicationService.ValidateEmailAsync(formState.Personal.Email);
        isValidatingEmail = false;

        if (!isValid)
        {
            emailError = "Email validation failed. Please use a valid email address.";
            return;
        }

        GoNext();
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        StateHasChanged();

        var application = formState.ToRecord();
        submittedId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitting = false;
    }
}

