.apply-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.completed {
    cursor: pointer;
    opacity: 0.8;
}

.step.completed:hover {
    opacity: 1;
}

.step.current {
    opacity: 1;
}

.step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: white;
    color: #666;
}

.step.current .step-number {
    border-color: #4361ee;
    background: #4361ee;
    color: white;
}

.step.completed .step-number {
    border-color: #2ecc71;
    background: #2ecc71;
    color: white;
}

.checkmark {
    font-size: 1.1rem;
}

.step-label {
    font-size: 0.75rem;
    margin-top: 0.3rem;
    text-align: center;
    max-width: 80px;
    color: #555;
}

.step.current .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-connector {
    width: 30px;
    height: 2px;
    background: #ddd;
    margin: 0 0.25rem;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #2ecc71;
}

/* Step Content */
.step-content {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #666;
    margin-bottom: 1.5rem;
}

/* Form Controls */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 500;
    color: #333;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
