}

.cover-letter-textarea {
    min-height: 200px;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.3rem;
}

.character-count.warning {
    color: #e74c3c;
    font-weight: 600;
}

